<script setup>import {ref} from 'vue';import {state,actions} from '../../domain/prototypeStore.js';import StatusTag from '../../components/StatusTag.vue';const msg=ref('');const review=()=>{const r=actions.reviewInventory();msg.value=r.message||(r.ok?'已复核并更新台账数量':'操作失败')}</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">资</div><div><h2>物资盘点</h2><p>台账快照、移动盘点、差异和复核更新</p></div><StatusTag :text="state.inventory.status"/></div><div v-if="msg" class="action-message">{{msg}}</div>
<article class="panel detail-grid"><div><small>计划</small><strong>{{state.inventory.planId}}</strong></div><div><small>站点</small><strong>{{state.inventory.station}}</strong></div><div><small>物资</small><strong>{{state.inventory.item}}</strong></div><div><small>台账快照</small><strong>{{state.inventory.bookQuantity}}</strong></div><div><small>现场数量</small><strong>{{state.inventory.actualQuantity??'待盘点'}}</strong></div><div><small>数量差异</small><strong :class="{danger:state.inventory.difference}">{{state.inventory.difference??'—'}}</strong></div></article>
<div class="button-row"><RouterLink class="primary-link" to="/h5/inventory">H5 盘点入口</RouterLink><button class="secondary-button" :disabled="state.inventory.status!=='待复核'" @click="review">复核并更新台账</button></div></section></template>